import React from 'react';

function Stack() {
  const categories = [
    {
      title: 'Linguagens',
      items: [
        ['javascript', 'JavaScript'],
        ['typescript', 'TypeScript'],
        ['python', 'Python'],
        ['c', 'C'],
        ['cplusplus', 'C++'],
      ],
    },
    {
      title: 'Frameworks & Bibliotecas',
      items: [
        ['react', 'ReactJS'],
        ['react', 'React Native'],
        ['nestjs', 'NestJS'],
        ['express', 'Express.js'],
        ['nodejs', 'Node.js'],
      ],
    },
    {
      title: 'Banco de Dados',
      items: [
        ['postgresql', 'PostgreSQL'],
        ['mysql', 'MySQL'],
        ['mongodb', 'MongoDB'],
      ],
    },
    {
      title: 'Ferramentas',
      items: [
        ['git', 'Git'],
        ['github', 'GitHub'],
        ['npm', 'npm'],
        ['figma', 'Figma'],
        ['docker', 'Docker'],
        ['dbeaver', 'DBeaver'],
      ],
    },
  ];

  return (
    <section id="stack" className="section">
      <div className="container">
        <div className="section__heading">
          <span className="eyebrow">Stack</span>
          <h2>Tecnologias que uso para construir produtos de ponta a ponta.</h2>
          <p>
            Combino front-end, back-end, dados e ferramentas de entrega para
            desenvolver produtos com velocidade e consistência.
          </p>
        </div>
        <div className="stack__grid">
          {categories.map((category) => (
            <div className="glass card stack__item" key={category.title}>
              <div className="stack__item-header">
                <span className="stack__item-tag">Core</span>
                <h3>{category.title}</h3>
              </div>
              <ul className="stack__list">
                {category.items.map(([icon, label]) => (
                  <li key={label}>
                    <img src={`/icons/${icon}.svg`} alt={label} />
                    <span>{label}</span>
                  </li>
                ))}
              </ul>
            </div>
          ))}
        </div>
      </div>
    </section>
  );
}

export default Stack;
